// Finalize reviewed catalog pages using OpenWiki 0.7.2 lifecycle APIs.
// Summary text is generated by Nebius; master layout is assembled locally.
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const pkg=process.env.OPENWIKI_PACKAGE_ROOT||path.join(process.env.APPDATA,'npm/node_modules/openwiki');
const api=await import(pathToFileURL(path.join(pkg,'dist/generation/repository-run.js')));
const definitions=JSON.parse(await fs.readFile(path.join(root,'catalog/page-claims.json'),'utf8'));
const {run,view}=await api.beginRepositoryRun({root,mode:'update',force:true,actor:{producerActor:'codex/wiki-summary-catalog',metadataModel:'nebius-service-summaries/local-master-renderer'}});
if(view.status==='noop')process.exit(0);
if(run.state.phase==='planning')await api.submitRepositoryPlan(run,{pages:Object.keys(definitions).map(name=>({path:'/openwiki/'+name,title:name.replace('.md',''),purpose:'Application map derived from compact service wiki summaries',seedPaths:['catalog/service-cards']})),deletePages:[]});
while(true){
 const next=await api.nextRepositoryPage(run);
 if(next.status==='complete')break;
 const filename=path.basename(next.job.path);
 const claimPath=path.join(root,'openwiki/.claims',filename.replace(/\.md$/,'.json'));
 let previous=[];
 try{previous=JSON.parse(await fs.readFile(claimPath,'utf8')).claims;}catch(error){if(error.code!=='ENOENT')throw error;}
 const entries=definitions[filename];
 if(!entries)throw new Error('No reviewed claim definitions for '+filename);
 const claims=entries.map(entry=>({...entry,...(previous.find(c=>c.statement===entry.statement)?{id:previous.find(c=>c.statement===entry.statement).id}:{})}));
 const retained=new Set(claims.map(c=>c.id).filter(Boolean));
 await api.submitRepositoryPage(run,{jobId:next.job.id,claims,retractedClaimIds:previous.filter(c=>!retained.has(c.id)).map(c=>c.id)});
}
console.log(await api.finishRepositoryRun(run));
